import { useEffect, useState } from 'react'
import type { Object3D } from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import markersUrl from './assets/markers.glb?url'
import eraserUrl from './assets/eraser.glb?url'

/**
 * The whiteboard's tools as real 3D models.
 *
 * - Markers: `markers.glb`, generated by scripts/build-marker.mjs: a glossy white barrel with a
 *   printed label, a colored ribbed cap with a clip, a colored end plug and a felt chisel nib.
 * - Eraser: `eraser.glb`, generated by scripts/build-eraser.mjs: a gray expanded-polystyrene block
 *   (fused beads, raised rim around a recessed top) on a white felt pad, with baked textures.
 *
 * Each model is re-based into a frame the board can use directly, and consumers clone it:
 * - marker: nib tip at the origin, barrel along +Y, label and clip facing +Z; capped it spans
 *   y = −0.0042 (cap dome) to 0.1285 (end plug). Its cap is a child named `…_Cap`.
 * - eraser: felt face at z = 0 facing −Z (toward the board), block up +Z, long side along X.
 */
export interface ToolModels {
  markers: Record<'black' | 'blue' | 'red', Object3D>
  eraser: Object3D
}

/** Real sizes (meters) of the models, for layout and the eraser's footprint. */
/** Capped marker, cap dome to end plug. */
export const MARKER_LENGTH = 0.1327
/** How far the cap's dome reaches past the nib tip (the model's origin). */
export const MARKER_TIP_OVERHANG = 0.0042
/** Radius of the cap, the widest part. */
export const MARKER_RADIUS = 0.00815
export const ERASER_SIZE = { w: 0.13, h: 0.05, height: 0.0323 }

const MARKER_NODES = { black: 'Marker_Black', blue: 'Marker_Blue', red: 'Marker_Red' } as const

let pending: Promise<ToolModels | null> | null = null
let loaded: ToolModels | null = null

export function loadToolModels(): Promise<ToolModels | null> {
  const loader = new GLTFLoader()
  pending ??= Promise.all([loader.loadAsync(markersUrl), loader.loadAsync(eraserUrl)])
    .then(([markers, eraser]) => {
      const marker = (name: string): Object3D => {
        const node = markers.scene.getObjectByName(name)
        if (!node) throw new Error(`markers.glb has no ${name}`)
        return node
      }
      loaded = {
        markers: { black: marker(MARKER_NODES.black), blue: marker(MARKER_NODES.blue), red: marker(MARKER_NODES.red) },
        // Already built in the tool frame.
        eraser: eraser.scene,
      }
      return loaded
    })
    .catch((err) => {
      // The board still works with the simple stand-ins.
      console.warn('Whiteboard tool models failed to load', err)
      return null
    })
  return pending
}

/** The tool models once loaded (null until then, or if they failed to load). */
export function useToolModels(): ToolModels | null {
  const [models, setModels] = useState(loaded)
  useEffect(() => {
    let live = true
    if (!loaded) void loadToolModels().then((m) => live && setModels(m))
    return () => {
      live = false
    }
  }, [])
  return models
}

/** A copy of a tool model for one place in the scene (geometry and materials are shared). */
export function placeModel(model: Object3D, name: string): Object3D {
  const o = model.clone()
  o.name = name
  o.traverse((c) => {
    c.raycast = () => {}
  })
  return o
}

/** Cap on (in the tray) or posted on the back end, the way you hold a marker to write. */
export function postCap(marker: Object3D, posted: boolean) {
  const cap = marker.children.find((c) => c.name.endsWith('_Cap'))
  if (!cap) return
  // Turned round and pushed onto the end plug: its open end (y = 0.0305) lands at y = 0.112.
  cap.rotation.set(posted ? Math.PI : 0, 0, 0)
  cap.position.set(0, posted ? 0.1425 : 0, 0)
}
